import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"49、【革】 離下兌上","description":"周易尚氏學 - 49、【革】 離下兌上","frontmatter":{"title":"49、【革】 離下兌上","description":"周易尚氏學 - 49、【革】 離下兌上"},"headers":[],"relativePath":"classics/shangshi/054.md","filePath":"classics/shangshi/054.md"}'),s={name:"classics/shangshi/054.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_49、【革】-離下兌上" tabindex="-1">49、【革】 離下兌上 <a class="header-anchor" href="#_49、【革】-離下兌上" aria-label="Permalink to “49、【革】 離下兌上”">​</a></h1><p>革改也。言水火更代用事也。離為日貞己。故曰己日。己日謂二。二離主爻。承陽應五。故曰己日乃孚。王弼等謂即日不孚、己日乃孚。訓己為過往。不辭甚矣。顧炎武日知錄。謂朱子發讀為戊己之己。當從之。按虞氏注云。離為日。孚謂坎。四動體離。故己日乃孚。是虞氏亦以離為己日。讀為戊己之己明甚。而非始於朱子發。元亨利貞。即春夏秋冬。象傳所謂四時也。四時更代。乃革之最大者。卦巽居春夏之交。離為夏。兌為秋。乾為冬。故曰元亨利貞。純取革義。辭雖與乾象同。義則殊也。</p><p>彖曰。革。水火相息。二女同居。其志不相得。曰革。己日乃孚。革而信之。文明以說。大亨以正。革而當。其悔乃亡。天地革而四時成。湯武革命。順乎天而應乎人。革之時大矣哉。</p><p>息長也。言更代用事也。但兌離皆陰卦。易之道陰遇陽。陽遇陰方誌得。若陰遇陰。陽遇陽。則為敵矣。中孕六三曰得敵。艮彖曰敵應。是也。故其志不相得。巽為志。二至上正反巽。故不相得。己中央土。仁義禮智信。信亦隸中央。故曰己日乃孚。革而信之。信故無悔。四時相代實相革。期無或爽。信也。湯武革命。天人皆應。亦信也。不信則不能革。故時之所關甚大。此其義也。</p><p>象曰。澤中有火。革。君子以治歷明時。</p><p>歷者日月星辰之所歷。識其處以定四時。書所謂敬授民時。大戴記之夏小正。小戴記之月令皆歷也。卦上兌為月。下離為日。乾為寒。離為暑。兌雨巽風皆備。故君子法之。以治歷明時。</p><p>初九。鞏用黃牛之革。</p><p>離外則故曰鞏。鞏固也。離為牛。左傳曰純離為牛。離六二雲黃離。故曰黃牛。乃虞翻則謂離無牛象。乾寶謂離父本坤。故曰黃牛。皆非也。離外堅為甲故為革。革皮去毛者也。固莫團於牛革。言初當勿用之時。不可妄動。宜固守也。牛革所以喻其固也。</p><h3 id="象曰。鞏用黃牛。不可以有為也。" tabindex="-1">象曰。鞏用黃牛。不可以有為也。 <a class="header-anchor" href="#象曰。鞏用黃牛。不可以有為也。" aria-label="Permalink to “象曰。鞏用黃牛。不可以有為也。”">​</a></h3><p>初潛龍勿用。故不可以有為。又上無應。即不信也。不信即不可革。</p><p>六二。己日乃革之。徵吉。無咎。</p><p>二離主爻。離貞己。故曰己。二有應。故曰己日乃革。二遇陽。故拉吉而無咎也。按二為日中。王弼以過往詁己日。故決知其非是。</p><h3 id="象曰。已日乃革之。行有嘉也。" tabindex="-1">象曰。已日乃革之。行有嘉也。 <a class="header-anchor" href="#象曰。已日乃革之。行有嘉也。" aria-label="Permalink to “象曰。已日乃革之。行有嘉也。”">​</a></h3><p>乾為嘉。行有嘉。謂二徵則遇陽 遇陽故人。</p><p>九三。徵兇。貞厲。革言三就。有孚</p><p>三臨重陽。陽遇陽則窒。故徵兇。卜問厲也。然三應在上。上兌為言。而兌為毀折。故曰革言。就即也。遇也。革言三就有孚者。言三雖得敵。不能應上。若上六即三。則甚順利而有孚也。兌為言。乾亦為言。言多故曰三就。又三在三爻。損六三雲。三人行。需上六雲三人來。皆以在三交。取數於三。三就者三遇也。謂革言來之多也。有孚者上孚於三也。易理失傳。舊解於徵兇之故。莫有明者。豈知徵兇貞厲。謂陽遇陽。下二句謂上應三。義不相屬也。</p><h3 id="象曰。革言三就。又何之矣。" tabindex="-1">象曰。革言三就。又何之矣。 <a class="header-anchor" href="#象曰。革言三就。又何之矣。" aria-label="Permalink to “象曰。革言三就。又何之矣。”">​</a></h3><p>之往也。又何之者。言上六即三。不必他往也。蓋革言日至則孚者眾。而事已審。革之而已。勿再猶豫不定也。</p><p>九四。悔亡。有孚。改命吉。</p><p>四失位。宜有悔。無應予則無孚。然九四居乾之中。乾為信。故無悔而有孚。巽為命。四至上巽覆。是改命也。易林人畜之夬也。太子扶蘇出於遠郊。佞幸成邪。改命生憂。即以夬上兌為改命本此也。改命則革也。蓋初以時未至而固守。二孚於天時。三孚於人事。至四遂實行改革矣。乾四雲或躍在淵。與此理同也。自覆象失傳。舊解皆以四變陰成既濟為改命。既濟者終正。何吉之有哉。非也。</p><h3 id="象曰。改命之吉。信志也。" tabindex="-1">象曰。改命之吉。信志也。 <a class="header-anchor" href="#象曰。改命之吉。信志也。" aria-label="Permalink to “象曰。改命之吉。信志也。”">​</a></h3><p>巽為志。改命則實行革命。故曰伸志。言得行其志也。志行故吉。</p><p>九五。大人虎變。未佔有孚</p><p>乾為大人為虎。大人虎變者。喻大人履九五之尊。威德誕敷。崇高巍煥。改易舊觀。故曰虎變。下有應。故未佔而有孚也。乾虎象失傳。後惟茹敦和俞樾知之。虞翻以坤為虎。宋衷以兌為虎。皆非。</p><h3 id="象曰。大人虎變-其文炳也。" tabindex="-1">象曰。大人虎變，其文炳也。 <a class="header-anchor" href="#象曰。大人虎變-其文炳也。" aria-label="Permalink to “象曰。大人虎變，其文炳也。”">​</a></h3><p>五應二。二離為文。故其文炳。</p><p>上六。君子豹變。小人革面。徵兇。居貞吉。</p><p>伏艮為君子。為豹。君子豹變者。謂革命後住命之動。皆得封拜而有茅土。尊顯富貴。易世成名。故曰豹變。陰稱小人。民為面。艮伏故革面。小人革面者。謂革命之後，除舊佈新。小民皆改易其視向也。面向也。史記項羽本紀。馬童面之。是也。上六當位，不宜動宜靜。故徵兇居吉。艮面象。易林遁之蒙雲。雲過吾面。以蒙坎為雲。艮為面。虞氏謂面指四。非。</p><h3 id="象曰。君子豹變。其文蔚也。小人革面。順以從君也。" tabindex="-1">象曰。君子豹變。其文蔚也。小人革面。順以從君也。 <a class="header-anchor" href="#象曰。君子豹變。其文蔚也。小人革面。順以從君也。" aria-label="Permalink to “象曰。君子豹變。其文蔚也。小人革面。順以從君也。”">​</a></h3><p>下應三。離為文。面向也。故曰順以從君。言下順乾也。</p>',30)])])}const f=e(s,[["render",t]]);export{_ as __pageData,f as default};
